"use strict";
const DATA=JSON.parse(document.getElementById('atlas-data').textContent);
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(n,d=3)=>Number(n).toFixed(d);
const SOURCES=Object.fromEntries(DATA.sources.map(s=>[s.id,s]));
const CATS=Object.fromEntries(DATA.categories.map(c=>[c.id,c]));
const DOCS=DATA.corpus;
const tokenize=s=>(String(s).toLowerCase().match(/[a-z0-9]+/g)||[]);
DOCS.forEach(d=>{d.tokens=tokenize(d.text);d.tf={};d.tokens.forEach(t=>d.tf[t]=(d.tf[t]||0)+1);});
const vocab=[...new Set(DOCS.flatMap(d=>d.tokens))];
const df=t=>DOCS.filter(d=>d.tf[t]).length;
const idf=t=>Math.log((DOCS.length+1)/(df(t)+1))+1;
const avgdl=DOCS.reduce((a,d)=>a+d.tokens.length,0)/DOCS.length;
const dot=(a,b)=>a.reduce((s,x,i)=>s+x*(b[i]||0),0);
const norm=a=>Math.sqrt(dot(a,a));
const cosine=(a,b)=>norm(a)&&norm(b)?dot(a,b)/(norm(a)*norm(b)):0;
const val=id=>$('#'+id).value, number=id=>Number(val(id)), checked=id=>$('#'+id).checked;
function sourceLine(ids){return `<div class="source-line"><span>READ THE SOURCE</span>${ids.map(id=>{let s=SOURCES[id];return `<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer" title="${esc(s.title)}">${esc(s.author.split(' · ')[0])} · ${s.year} ↗</a>`;}).join('')}</div>`;}
function range(id,label,min,max,step,value,help=''){return `<label class="control" for="${id}"><span>${label}<output id="${id}-value" for="${id}">${value}</output></span><input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}">${help?`<div class="control-help">${help}</div>`:''}</label>`;}
function select(id,label,options,value){return `<label class="control" for="${id}"><span>${label}</span><select id="${id}">${options.map(([v,t])=>`<option value="${v}" ${v===value?'selected':''}>${t}</option>`).join('')}</select></label>`;}
function textInput(id,label,value,help=''){return `<label class="control" for="${id}"><span>${label}</span><input type="text" id="${id}" value="${esc(value)}" spellcheck="false">${help?`<div class="control-help">${help}</div>`:''}</label>`;}
function check(id,label,on=false){return `<label class="control check" for="${id}"><input type="checkbox" id="${id}" ${on?'checked':''}><span>${label}</span></label>`;}
function lab(id,title,tag,controls,wide=false){return `<section id="lab-${id}" class="lab ${wide?'wide-lab':''}" aria-labelledby="${id}-title"><header class="lab-header"><div><span class="eyebrow">TRY THE IDEA YOURSELF</span><h2 id="${id}-title">${title}</h2></div><span class="lab-tag">${tag}</span></header><p class="lab-instruction">${esc((CATS[id]?.lesson||DATA.evaluation_lesson).experiment)}</p><div class="lab-body"><div class="controls">${controls}</div><div class="result" id="${id}-result" aria-live="polite" aria-atomic="true"></div></div></section>`;}
function metrics(items){return `<div class="metric-grid">${items.map(([v,t])=>`<div class="metric"><strong>${v}</strong><small>${t}</small></div>`).join('')}</div>`;}
function rows(items,places=3){if(!items.length)return '<div class="empty">No matches. Try a broader query.</div>';const max=Math.max(...items.map(x=>x.score),.001);return items.map((x,i)=>`<div class="rank-row"><span class="rank-pos">${i+1}</span><div class="rank-label">${esc(x.label||`${x.d.id} · ${x.d.title}`)}${x.sub?`<small>${esc(x.sub)}</small>`:''}<div class="track"><b style="width:${Math.max(0,x.score/max*100)}%"></b></div></div><span class="rank-value">${num(x.score,places)}</span></div>`).join('');}
function corpus(){return `<details class="corpus-toggle"><summary>Read exactly what the labs search · 8 invented documents</summary><p class="control-help">Only each body below is searched. Titles label documents; they contribute no tokens or score. Processing splits letters/digits into lowercase tokens, with no word-form mapping and no common-word removal. The grades are teaching judgments for “solar battery storage”: 0 means not useful here; 1 loosely related; 2 useful; 3 directly useful. Different questions can deserve different grades.</p><div class="corpus-list">${DOCS.map(d=>`<article class="corpus-doc"><h3><code>${d.id}</code>Display title: ${esc(d.title)}</h3><p><strong>SEARCHED BODY:</strong> ${esc(d.text)}</p><span class="pill">${d.type} · ${d.year}</span><span class="pill warm">${d.tokens.length} body tokens · grade ${d.rel}/3</span></article>`).join('')}</div></details>`;}
const NAV_NAMES={boolean:'Match exact words',lexical:'Weigh matching words',probabilistic:'Limit repetition',expansion:'Reword the request',dense:'Compare meanings',sparse:'Learn word clues',late:'Match each query part',indexes:'Search faster',ranking:'Reorder a shortlist',fusion:'Combine searchers',structured:'Follow connections',multimodal:'Search images & more',frontier:'Search iteratively',evaluation:'Check the results'};

function flowDiagram(l,id){return `<figure class="idea-diagram" aria-labelledby="idea-caption-${id}"><figcaption id="idea-caption-${id}">SEE THE IDEA IN THREE STEPS <span>Illustrative example</span></figcaption><ol>${l.steps.map(([title,example],i)=>`<li><span class="flow-number">0${i+1}</span><h3>${esc(title)}</h3><p>${esc(example)}</p></li>`).join('')}</ol></figure>`;}
function lessonBlock(l,id){return `<section class="intuition-lesson" aria-labelledby="intuition-${id}"><div class="section-head"><h2 id="intuition-${id}">Start with the idea.</h2><button type="button" class="small-button" data-go-lab="${id}">Jump to the experiment ↓</button></div><div class="intuition-story">${l.story.slice(1).map(t=>`<p>${esc(t)}</p>`).join('')}</div>${flowDiagram(l,id)}<section class="word-guide" aria-labelledby="words-${id}"><span class="eyebrow">THE NAMES, NOW THAT THE IDEA IS FAMILIAR</span><h3 id="words-${id}">A few words we will use.</h3><dl>${l.terms.map(([term,meaning])=>`<div><dt>${esc(term)}</dt><dd>${esc(meaning)}</dd></div>`).join('')}</dl></section><div class="note lesson-takeaway"><strong>Keep this in mind.</strong> ${esc(l.takeaway)}</div></section>`;}
function wordFormDemo(){return `<section class="word-form-demo" aria-labelledby="word-form-title"><span class="eyebrow">A SMALL EXACT-MATCH CHECK</span><h2 id="word-form-title">Does battery match batteries?</h2><p>First compare two bodies that differ only in word form. This example is independent of the eight-document collection.</p><div class="word-form-controls">${select('form-query','Word to search for',[['battery','battery'],['batteries','batteries']],'battery')}${check('form-map','Apply the explicit mapping batteries → battery to both query and bodies')}</div><div id="word-form-result" aria-live="polite"></div><p class="control-help">This checkbox implements only that one dictionary mapping. It is not a general stemmer or lemmatizer and never changes the shared collection’s strict matching.</p>${sourceLine(['wordforms'])}</section>`;}
function bodyEvidence(d,terms){return d.tokens.map((t,i)=>terms.includes(t)?`<mark title="Body token position ${i+1}">${esc(t)}</mark>`:esc(t)).join(' ');}
function astTerms(ast){if(ast.op==='TERM')return tokenize(ast.term);return [...new Set([...astTerms(ast.a),...(ast.b?astTerms(ast.b):[])])];}
function updateWordForms(){const raw=val('form-query'),mapped=checked('form-map'),process=t=>mapped&&t==='batteries'?'battery':t,q=process(raw),docs=[['S1','battery storage'],['S2','batteries storage']];$('#word-form-result').innerHTML=`<div class="table-wrap"><table class="mini-table"><thead><tr><th>Body actually searched</th><th>Tokens after this rule</th><th>Matches ${esc(raw)}?</th></tr></thead><tbody>${docs.map(([id,body])=>{let tokens=tokenize(body).map(process),hit=tokens.includes(q);return `<tr data-fixture="${id}"><td>${id}: ${body}</td><td>${tokens.join(' · ')}</td><td><span class="status ${hit?'':'bad'}">${hit?'YES':'NO'}</span></td></tr>`;}).join('')}</tbody></table></div><p><strong>${mapped?'With the stated mapping, both bodies contain the same processed query token.':'With lowercase-only processing, battery and batteries remain different tokens.'}</strong> No relevance score is assigned.</p>`;}
function lexicalTrace(query,mode,d){const qt=tokenize(query).reduce((o,t)=>(o[t]=(o[t]||0)+1,o),{}),terms=[...new Set([...vocab,...Object.keys(qt)])],q=terms.map(t=>(qt[t]||0)*idf(t)),v=terms.map(t=>(d.tf[t]||0)*idf(t)),raw=dot(q,v),score=mode==='cosine'?cosine(q,v):raw;return `<details class="calculation-trace"><summary>Follow ${d.id}’s score, one word at a time</summary><p>Multiply each query word’s count by its rarity weight. Do the same for the document. Multiply those two weights, then add the shared-word contributions.</p><div class="table-wrap"><table class="mini-table"><thead><tr><th>Token</th><th>Query count</th><th>Body count</th><th>df / 8</th><th>IDF</th><th>Weight product</th></tr></thead><tbody>${Object.keys(qt).map(t=>`<tr><td>${esc(t)}</td><td>${qt[t]}</td><td>${d.tf[t]||0}</td><td>${df(t)}</td><td>${num(idf(t),5)}</td><td>${num(qt[t]*(d.tf[t]||0)*idf(t)**2,5)}</td></tr>`).join('')}</tbody></table></div><div class="formula">Shared-word products add to ${num(raw,6)}.<br>${mode==='cosine'?`Query length in number space = ${num(norm(q),6)}.<br>Document length in number space = ${num(norm(v),6)}.<br>${num(raw,6)} ÷ (${num(norm(q),6)} × ${num(norm(v),6)}) = ${num(score,6)}`:`No division by vector lengths: final score = ${num(score,6)}`}</div><p>Numerical vector length is not token count. Document length here includes weights for its non-query words too. Intermediate values are rounded for display; computation uses full precision.</p></details>`;}
function bm25Parts(d,query,k1,b){return [...new Set(tokenize(query))].map(t=>{let tf=d.tf[t]||0,rarity=Math.log(1+(DOCS.length-df(t)+.5)/(df(t)+.5)),lengthFactor=1-b+b*d.tokens.length/avgdl,multiplier=tf?tf*(k1+1)/(tf+k1*lengthFactor):0;return{t,tf,df:df(t),rarity,lengthFactor,multiplier,contribution:rarity*multiplier};});}
function bmTrace(d,query,k1,b){const parts=bm25Parts(d,query,k1,b);return `<details class="calculation-trace"><summary>Follow ${d.id}’s BM25 score, one word at a time</summary><p>For every query word, multiply its collection-rarity weight by the repetition credit after the length adjustment. A word absent from the body contributes zero.</p><div class="formula">${d.id} has ${d.tokens.length} body tokens. The collection has ${DOCS.reduce((n,d)=>n+d.tokens.length,0)} tokens across 8 documents.<br>Average length = ${num(avgdl,3)}.<br>Length factor = 1 − ${b} + ${b} × ${d.tokens.length}/${num(avgdl,3)} = ${num(parts[0]?.lengthFactor||0,6)}.</div><div class="table-wrap"><table class="mini-table"><thead><tr><th>Token</th><th>Count</th><th>df</th><th>Rarity weight</th><th>Repetition credit</th><th>Contribution</th></tr></thead><tbody>${parts.map(p=>`<tr><td>${esc(p.t)}</td><td>${p.tf}</td><td>${p.df}</td><td>${num(p.rarity,5)}</td><td>${num(p.multiplier,5)}</td><td>${num(p.contribution,5)}</td></tr>`).join('')}</tbody></table></div><div class="formula">${parts.map(p=>num(p.contribution,6)).join(' + ')} = ${num(parts.reduce((s,p)=>s+p.contribution,0),6)}</div><p>The repetition credit is count × (k₁+1) ÷ [count + k₁ × length factor]. Rarity weight is ln(1+(8−df+.5)/(df+.5)). All arithmetic uses unrounded values.</p></details>`;}
function likelihoodTrace(d,query,mu){const terms=tokenize(query),total=DOCS.reduce((s,x)=>s+x.tokens.length,0),unique=[...new Set(terms)],parts=unique.map(t=>{let count=DOCS.reduce((s,x)=>s+(x.tf[t]||0),0),background=count/total,p=((d.tf[t]||0)+mu*background)/(d.tokens.length+mu);return{t,count,background,p,qcount:terms.filter(x=>x===t).length};}),logScore=parts.reduce((s,p)=>s+p.qcount*Math.log(p.p),0);return `<details class="calculation-trace"><summary>Follow ${d.id}’s query-word probabilities</summary><p>Add the page’s token count to μ times the collection token frequency. Divide by the page length plus μ. Multiply probabilities for all query occurrences; equivalently, add their natural logarithms.</p><div class="table-wrap"><table class="mini-table"><thead><tr><th>Token</th><th>Page count</th><th>Collection count / ${total}</th><th>Smoothed probability</th></tr></thead><tbody>${parts.map(p=>`<tr><td>${esc(p.t)}</td><td>${d.tf[p.t]||0}</td><td>${p.count} / ${total}</td><td>${num(p.p,6)}</td></tr>`).join('')}</tbody></table></div><div class="formula">Total log likelihood = ${num(logScore,6)}.<br>Query occurrences = ${terms.length}.<br>Displayed geometric mean = exp(${num(logScore,6)} / ${terms.length}) = ${num(Math.exp(logScore/terms.length),6)}.</div><p>This is a probability for query tokens under a word model, not a probability that the page answers the question. No unknown-token probability is invented.</p></details>`;}

const navGroups=[['START EXPLORING',[['overview','A map of retrieval'],['timeline','The timeline']]],['MATCH & REPRESENT',DATA.categories.slice(0,7).map(c=>[c.id,NAV_NAMES[c.id]])],['COMPOSE & SERVE',DATA.categories.slice(7,12).map(c=>[c.id,NAV_NAMES[c.id]])],['THE NEXT CHAPTER',[['frontier','Search iteratively'],['evaluation','Check the results'],['sources','Papers & further reading']]]];
const TABLIST=navGroups.flatMap(g=>g[1]);
$('#tabs').innerHTML=navGroups.map(([name,items])=>`<div class="nav-group" role="presentation">${name}</div>${items.map(([id,title])=>`<button type="button" class="nav-tab" role="tab" id="tab-${id}" aria-controls="panel-${id}" aria-selected="false" tabindex="-1" data-tab="${id}"><span class="nav-no">${String(TABLIST.findIndex(x=>x[0]===id)+1).padStart(2,'0')}</span><span>${title}</span></button>`).join('')}`).join('');
function panel(id,body){return `<section id="panel-${id}" class="panel" role="tabpanel" tabindex="0" aria-labelledby="tab-${id}" hidden>${body}</section>`;}
function heading(kicker,title,question,intro,era=''){return `<div class="page-top"><span class="chapter-no">${kicker}</span><span class="era">${era}</span></div><h1 class="page-title">${title}</h1><div class="page-question">${question}</div><p class="intro">${intro}</p>`;}
const heroSVG=`<svg viewBox="0 0 460 392" role="img" aria-label="Diagram: exact word matches and semantic neighbors feed a combined ranked result list"><defs><pattern id="dots" width="18" height="18" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".7" fill="#bdc9bb"/></pattern><marker id="arrowhead" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10" fill="none" stroke="#90a69b" stroke-width="1.5"/></marker></defs><rect x="5" y="12" width="445" height="340" fill="url(#dots)" opacity=".5"/><circle cx="226" cy="180" r="127" fill="none" stroke="#d8e1d5"/><circle cx="226" cy="180" r="87" fill="none" stroke="#d8e1d5" stroke-dasharray="3 7"/><path d="M226 78L115 137 M226 78L339 137 M115 214L193 282 M339 214L260 282" stroke="#90a69b" stroke-width="1.4" fill="none" marker-end="url(#arrowhead)"/><rect x="117" y="32" width="218" height="49" rx="8" fill="#fffefa" stroke="#bacdbd"/><text x="135" y="53" font-family="monospace" font-size="8" fill="#7d8e81">THE INFORMATION NEED</text><text x="135" y="69" font-family="Georgia" font-size="14" fill="#203439">“solar battery storage”</text><rect x="20" y="136" width="180" height="84" rx="8" fill="#fffefa" stroke="#c1d1c0"/><text x="37" y="158" font-family="monospace" font-size="8" fill="#087a72">01 / MATCH WORDS</text><rect x="36" y="172" width="63" height="25" rx="4" fill="#e5eee9"/><text x="44" y="188" font-family="monospace" font-size="10" fill="#087a72">battery</text><rect x="105" y="172" width="77" height="25" rx="4" fill="#f5e8dd"/><text x="112" y="188" font-family="monospace" font-size="10" fill="#ba583c">storage</text><rect x="250" y="136" width="188" height="84" rx="8" fill="#fffefa" stroke="#c1d1c0"/><text x="266" y="158" font-family="monospace" font-size="8" fill="#087a72">02 / MATCH MEANING</text><path d="M273 201L300 179L321 194L347 172L375 195L415 178" stroke="#c4d4bf" stroke-width="1" fill="none"/><circle cx="300" cy="179" r="4" fill="#087a72"/><circle cx="321" cy="194" r="3" fill="#9dbda4"/><circle cx="347" cy="172" r="5" fill="#ba583c"/><circle cx="375" cy="195" r="3" fill="#9dbda4"/><circle cx="415" cy="178" r="3" fill="#9dbda4"/><rect x="124" y="276" width="220" height="84" rx="8" fill="#203c3d"/><text x="141" y="298" font-family="monospace" font-size="8" fill="#b8d2bd">03 / FUSE &amp; RERANK</text><text x="141" y="321" font-family="monospace" font-size="9" fill="#82af9e">01</text><text x="165" y="321" font-family="Georgia" font-size="13" fill="#fffefa">Batteries balance the grid</text><text x="141" y="344" font-family="monospace" font-size="9" fill="#82af9e">02</text><text x="165" y="344" font-family="Georgia" font-size="13" fill="#fffefa">Power after sunset</text></svg>`;
function overview(){return `<div class="hero"><div><div class="eyebrow">UNIT 01 · HOW SEARCH WORKS</div><h1>From matching words<br>to finding <em>meaning.</em></h1><p class="hero-copy">You have a question and a collection of pages. How do you find the useful ones, and which should you read first? Start with that everyday problem, try small examples, then learn the names and calculations behind the ideas.</p><div class="hero-actions"><a class="primary" href="#boolean">Start with exact matching <span>↗</span></a><a class="text-link" href="#timeline">See how the ideas developed →</a></div></div><div class="hero-visual">${heroSVG}<p class="hero-caption">A CONCEPTUAL PIPELINE · NOT A MODEL PERFORMANCE RESULT</p></div></div><div class="stats"><div class="stat"><b>${DATA.categories.length+1}</b><span>method & evaluation families</span></div><div class="stat"><b>${DATA.categories.reduce((n,c)=>n+c.methods.length,0)}</b><span>ideas, explained before their equations</span></div><div class="stat"><b>14</b><span>interactive learning labs</span></div><div class="stat"><b>${DATA.sources.length}</b><span>papers, chapters & guides</span></div></div><div class="section-head"><h2>Start with three familiar things.</h2><span class="eyebrow">NO SPECIAL BACKGROUND NEEDED</span></div><div class="starter-definitions"><div><h3>A request</h3><p>The words or question you type. We call it a <strong>query</strong>.</p></div><div><h3>An item to search</h3><p>A page, passage, image or record. We often call one item a <strong>document</strong>.</p></div><div><h3>Something useful</h3><p>An item that helps with this particular request is <strong>relevant</strong>. Sharing a word or a topic alone may not be enough.</p></div></div><p class="lead"><strong>Retrieval</strong> means finding useful items from a collection. A simple search may only decide which items match. A ranked search also puts them in an order.</p><div class="section-head"><h2>One search. Several different jobs.</h2></div><p class="lead">Think of finding books in a library: describe what you need, gather possible books, inspect the promising ones, then check whether the pile answers the question.</p><div class="concept-grid"><div class="concept"><span class="concept-no">01 / DESCRIBE</span><h3>What clues do we keep?</h3><p>We might keep exact words, a numerical description of meaning, or links between named things. This is the <strong>representation</strong>.</p></div><div class="concept"><span class="concept-no">02 / GATHER</span><h3>Which items get considered?</h3><p>Find a manageable pile of possibilities. Each is a <strong>candidate</strong>. An item missing from this pile cannot be reordered later.</p></div><div class="concept"><span class="concept-no">03 / ORDER</span><h3>What should we read first?</h3><p>Use a rule or model to place useful candidates early. This is <strong>ranking</strong>. A second pass over a shortlist is <strong>reranking</strong>.</p></div><div class="concept"><span class="concept-no">04 / CHECK</span><h3>Did the pile help?</h3><p>Count useful items recovered, inspect their positions, and check what evidence is still missing. This is <strong>evaluation</strong>.</p></div></div><div class="note"><strong>The running example.</strong> The request is “solar battery storage”. D1’s body uses those exact words. D2 describes related ideas with different words. The chapters show why a word-only search and a meaning-based search may find different candidates. All documents and neural scores in this teaching collection are invented.</div><div class="section-head"><h2>Choose the question you want to understand.</h2><span class="eyebrow">ONE CHAPTER PER FAMILY</span></div><div class="map-grid">${DATA.categories.map((c,i)=>`<a class="map-item" href="#${c.id}"><span class="map-number">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(c.lesson.title)}</h3><p>${esc(c.name)}</p></div><span class="arrow">↗</span></a>`).join('')}<a class="map-item" href="#evaluation"><span class="map-number">14</span><div><h3>Check what was found—and what came first.</h3><p>Evaluation & tradeoffs</p></div><span class="arrow">↗</span></a></div><div class="section-head"><h2>A path from everyday intuition to technical detail.</h2></div><div class="pathway"><a href="#boolean">Exact words</a><span>→</span><a href="#lexical">Word importance</a><span>→</span><a href="#probabilistic">Repetition and length</a><span>→</span><a href="#dense">Meaning</a><span>→</span><a href="#fusion">Combine searchers</a><span>→</span><a href="#ranking">Read the shortlist carefully</a><span>→</span><a href="#evaluation">Check it</a></div><p class="lead">Each chapter begins with a situation, a small diagram and definitions. Try its experiment next. Open “terminology and calculation” in a method note when you want the formal account; the symbols are explained before the equation.</p>${corpus()}<div class="note warm"><strong>What is actually computed?</strong> Word matches, arithmetic scores, numerical similarities, combined votes and evaluation measures are calculated in your browser. Numerical descriptions supplied by neural models are replaced with visible, invented examples. The graph, visual-page and iterative-search demonstrations are explanatory schematics. No language model or external API runs.</div><div class="section-head"><h2>Read the ideas at their source.</h2><a class="text-link" href="#sources">Browse ${DATA.sources.length} annotated references ↗</a></div><div class="source-preview"><div><a href="${SOURCES.boolean.url}" target="_blank" rel="noopener">Start with the Stanford retrieval book ↗</a><p>A foundational textbook that develops search through worked examples.</p></div><div><a href="${SOURCES.retrievearticle.url}" target="_blank" rel="noopener">See a practical retrieve-then-rerank guide ↗</a><p>Connect the shortlist idea to actual model choices.</p></div></div>`;}
function timeline(){return heading('A BRIEF HISTORY','Search did not evolve in a straight line.','New branches grew. Earlier ideas kept working.','Each milestone starts with a problem people wanted to solve, then names the research idea. Look for the recurring needs: avoid reading everything, find different wording, choose the best order, and gather enough evidence. Dates mark publications or approximate development periods.','1950s → 2026')+`<div class="timeline-tools" role="group" aria-label="Filter historical era">${[['all','All eras'],['early','Before 2000'],['middle','2000–2020'],['recent','2021–2026']].map(([v,t])=>`<button class="chip" type="button" data-era="${v}" aria-pressed="${v==='all'}">${t}</button>`).join('')}</div><p class="timeline-legend">Select a milestone to see why it mattered, read the source and jump to its method family.</p><div class="timeline-layout"><div class="timeline-list" id="timeline-list"></div><div class="timeline-detail" id="timeline-detail" aria-live="polite"></div></div><div class="note">The underlying ideas predate many landmark papers. Boolean logic is older than computerized retrieval; the periods shown here describe information-retrieval practice. A timeline is a map of influential developments, not a claim of sole invention.</div>`;}
function methodCard(m,c,i){const l=m.lesson;return `<details class="method" id="method-${c.id}-${i}" ${i===0?'open':''}><summary><div><span class="eyebrow">IDEA ${String(i+1).padStart(2,'0')}</span><h3>${esc(l.title)}</h3><span class="method-name">Technical name: ${esc(m.title)}</span></div></summary><div class="method-content"><h4>Why this exists</h4><p>${esc(l.need)}</p><h4>Picture it this way</h4><p class="example">${esc(l.intuition)}</p><details class="technical-note"><summary>Then explore the terminology and calculation</summary><div class="terms-first"><h4>Define the terms first</h4><p>${esc(l.terms)}</p></div><p>${esc(m.idea)}</p><h4>What the symbols mean</h4><p>${esc(l.notation)}</p><div class="formula">${esc(m.formula)}</div><h4>Worked illustration</h4><p>${esc(m.example)}</p><p class="control-help">Unless a shared document ID is named, this is a separate illustrative example.</p><h4>When it helps</h4><p>${esc(m.use)}</p><h4>Where it can fail</h4><p>${esc(m.limit)}</p>${sourceLine(m.refs)}</details></div></details>`;}
function categoryPanel(c,i){const l=c.lesson;return heading(`CHAPTER ${String(i+1).padStart(2,'0')} · ${esc(c.name)}`,esc(l.title),esc(c.question),esc(l.story[0]),c.era)+lessonBlock(l,c.id)+(c.id==='boolean'?wordFormDemo():'')+labMarkup(c.id)+`<div class="section-head"><h2>More ways to use the idea.</h2><button type="button" class="small-button" data-expand="${c.id}">Expand all notes</button></div><p class="lead method-intro">Each note begins with a problem and a concrete picture. The terminology, notation and worked calculation are inside a separate optional section.</p><div class="method-grid">${c.methods.map((m,j)=>methodCard(m,c,j)).join('')}</div><details class="chapter-background"><summary>The formal family description and research sources</summary><p>${esc(c.intro)}</p><p>${esc(c.insight)}</p>${sourceLine(c.sources)}</details>`+(['boolean','lexical','probabilistic','expansion','ranking','fusion'].includes(c.id)?corpus():'')+`<div class="panel-bottom">${i?`<a href="#${DATA.categories[i-1].id}">← ${NAV_NAMES[DATA.categories[i-1].id]}</a>`:'<a href="#timeline">← The timeline</a>'}<a href="#${i<DATA.categories.length-1?DATA.categories[i+1].id:'evaluation'}">${i<DATA.categories.length-1?NAV_NAMES[DATA.categories[i+1].id]:'Check the results'} →</a></div>`;}
function labMarkup(id){
 switch(id){
case 'boolean':return lab('boolean','Decide which bodies pass the rule.','LITERAL BODY-TOKEN MATCHES',textInput('bool-query','Rule to check','solar AND (battery OR storage)','Use uppercase AND / OR / NOT, parentheses and quoted phrases. NOT is evaluated first, then AND, then OR.')+`<div class="tile-row"><button class="small-button" data-bool='battery'>Try battery</button><button class="small-button" data-bool='batteries'>Try batteries</button><button class="small-button" data-bool='"battery storage"'>Try a phrase</button><button class="small-button" data-bool='storage AND NOT battery'>Try exclusion</button></div>`+check('bool-filter','Also require a report from 2020 onward')+'<div class="note">The result is KEEP or SKIP. Matched words appear inside the body, so you can verify every decision. Titles do not participate.</div>');
case 'lexical':return lab('lexical','Watch distinctive words gain influence.','SCORES CALCULATED HERE',textInput('lex-query','Words to search for','solar battery storage')+select('lex-mode','How should the weighted lists be compared?',[['cosine','Compare proportions · cosine'],['dot','Add raw contributions · dot product']],'cosine')+'<div class="note">Count occurrences, weight words by how rare they are across pages, then compare. Open a score trace to follow every multiplication and division.</div>');
case 'probabilistic':return lab('probabilistic','Change repetition and length credit.','SCORES CALCULATED HERE',textInput('bm-query','Words to search for','solar battery storage')+select('bm-mode','Which question should the score answer?',[['bm25','How strong is the word evidence? · BM25'],['lm','How likely are the query words? · language model']],'bm25')+range('bm-k1','Extra credit for repeats · k₁',0,3,.1,1.2,'At 0, one occurrence and many occurrences receive the same credit. Larger values reward extra mentions more.')+range('bm-b','Adjust for page length · b',0,1,.05,.75,'0 removes the length adjustment. 1 uses the full document-to-average-length ratio.')+range('lm-mu','Background word evidence · μ',1,300,1,100,'Used only by the word-probability model. Higher values rely more on the whole collection’s vocabulary.'));
case 'expansion':return lab('expansion','Change the wording. Find new pages.','FIXED REWRITES · REAL SCORES',select('exp-mode','What extra search clues should we use?',[['original','Only the original words'],['synonym','Add known related words'],['pseudo','Borrow words from an early result'],['hyde','Use a fixed answer-like rewrite']],'original')+range('exp-weight','Influence of extra words',0,1,.1,.6,'Original words have weight 1. An extra word with weight 0 contributes nothing.')+`<p class="control-help">Original request: “power after sunset”. These rewrites are teaching fixtures, not generated by a running language model. Actual HyDE uses a dense encoder; this example uses the shared word-based calculation.</p>`);
case 'dense':return lab('dense','Move the request around a small meaning map.','INVENTED INPUTS · REAL GEOMETRY',range('dense-angle','Request direction · degrees',0,90,1,30,'0 points along the energy-storage axis; 90 points along transport. These two named axes are only for teaching.')+select('dense-metric','What should count as similar?',[['cosine','Same direction · cosine'],['dot','Direction and list length · dot product']],'cosine')+check('dense-scale','Multiply every number in the car vector by 3')+`<div class="note">A vector is a number list. Multiplying all its entries stretches it without changing its direction. Real embedding dimensions are usually not named human concepts.</div>`);
case 'sparse':return lab('sparse','Add useful word clues, then drop weak ones.','INVENTED WEIGHTS · REAL SUM',range('sparse-expansion','Strength of related-word clues',0,1,.1,.8)+range('sparse-threshold','Drop weights smaller than',0,1,.05,.2,'The threshold applies to query clues only. A clue exactly at the threshold stays.')+`<p class="control-help">Request: “renewable storage”. The fixed teaching model may also add battery, solar and grid. Document weights stay fixed, so you can isolate the change in the query.</p>`);
case 'late':return lab('late','Find the best support for each query word.','INVENTED CELLS · REAL MAXIMA',select('late-doc','Which document should we compare?',[['balanced','A · supports both solar and storage'],['one','B · mainly supports solar'],['duplicate','C · repeats the same evidence']],'balanced')+check('late-storage','Require support for “storage” as well as “solar”',true)+`<div class="note">Each row represents one query part. Find its largest cell, then add one largest value per row. Highlighting two equal cells does not mean both count.</div>`);
case 'indexes':return lab('indexes','Look in selected groups before searching everywhere.','FIXED GROUPS · REAL DISTANCES',range('ivf-probe','Groups to visit · nprobe',1,3,1,1,'Visit groups in order of their centers’ distance to the request. Then compare the actual points inside those groups.')+range('ivf-y','Move the request vertically',.1,.9,.05,.5)+`<p class="control-help">Six 2D points, three fixed groups, two requested neighbors. This is an IVF-style grouping example. It is not HNSW, which uses connected neighbors rather than this group-probing rule.</p>`);
case 'ranking':return lab('ranking','Improve the order without inventing candidates.','FIXED SECOND-STAGE SCORES',select('rerank-source','Where should the shortlist come from?',[['lexical','Exact body-word matches only · BM25'],['hybrid','Combine word and illustrative meaning lists']],'lexical')+range('rerank-depth','Request up to this many candidates',1,8,1,3)+check('rerank-on','Apply the more careful second-stage scorer',true)+`<div class="note">Request: “solar battery storage”. Source orders are calculated. Meaning scores and second-stage scores are written teaching fixtures. Word-only search returns only positive word matches.</div>`);
case 'fusion':return lab('fusion','Combine the lists. Inspect every vote.','COMBINATION CALCULATED HERE',select('fusion-mode','How should the lists be combined?',[['rrf','Vote by rank position · weighted RRF'],['score','Rescale and blend the scores'],['mmr','Balance relevance and variety · MMR']],'rrf')+range('fusion-depth','Results to take from each searcher',1,8,1,4,'This is a maximum. Word search has only 7 positive matches for this query.')+range('fusion-k','Soften rank differences · RRF k',0,100,1,60,'Larger k makes rank 1 and rank 2 contribute more similarly. It does not request more results.')+range('fusion-alpha','Word-source influence / MMR relevance share',0,1,.05,.5,'For fusion, α weights words and 1−α weights meaning. For MMR, λ weights relevance and 1−λ penalizes repetition.')+check('fusion-duplicate','Give the word searcher a second identical vote')+`<div class="note">Word scores are computed from the shown bodies. Meaning scores are invented. With equal weights, this RRF score is half the unweighted sum; the order is unchanged.</div>`);
case 'structured':return lab('structured','Connect the facts needed by the question.','INVENTED RECORDS · REAL LOOKUP',select('graph-mode','How far should we look?',[['one','Follow one connection · find the product'],['two','Follow two connections · find the material'],['summary','Read the fixed group summary']],'one')+check('graph-edge','Keep the record linking product to material',true)+`<p class="control-help">Question: “Which material is used by the product Aurora makes?” Every company and record here is invented. The summary is a fixed illustration, not a model-generated GraphRAG report.</p>`);
case 'multimodal':return lab('multimodal','Check whether the needed clue survives.','A REPRESENTATION SCHEMATIC',select('visual-mode','What should the stored description retain?',[['text','Only an unordered bag of words/numbers'],['layout','Text with table rows preserved'],['visual','The page image and visual regions']],'text')+select('visual-query','What does the reader want to know?',[['table','Which row has the longest cycle life?'],['chart','Which curve declines fastest?']],'table')+`<div class="note">This shows what information remains available. It does not simulate CLIP or ColPali accuracy. Good text extraction can preserve table structure; visual models can still make interpretation errors.</div>`);
case 'frontier':return lab('frontier','Use the next search to fill a gap.','SCRIPTED SEARCH DECISIONS',range('agent-budget','Maximum number of searches',1,3,1,1)+check('agent-diverse','Choose a missing evidence aspect next',true)+`<p class="control-help">Invented task: compare cost and durability under comparable conditions. Every evidence item is prewritten. Coverage is the calculated fraction of the three required aspects supported in this trace.</p>`);
 }
 return '';
}
function evaluation(){const l=DATA.evaluation_lesson;return heading('CHAPTER 14 · EVALUATION',l.title,'Coverage, wasted reading and early useful results are different questions.',l.story[0],'From shared test collections to evidence checks')+lessonBlock(l,'evaluation')+`<div class="note"><strong>Teaching judgments:</strong> this is one invented collection and one fixed request, “solar battery storage”. Grade 0 means unhelpful here; 1 loosely related; 2 useful; 3 directly useful. Five documents have grades above zero, so all five count as relevant for precision, recall and reciprocal rank. These generous example judgments are inspectable, not universal ground truth.</div>`+lab('evaluation','Move results and watch the measures respond.','MEASURES CALCULATED HERE',range('eval-k','How many leading results should we inspect? · k',1,8,1,5)+select('eval-preset','Start from this order',[['bm25','The body-word score order'],['ideal','Best possible grade order'],['reverse','Lowest grades first'],['semantic','Illustrative meaning-score order']],'bm25')+`<div><span class="eyebrow">TRY THIS</span><p class="control-help">Move an item with grade 0 above a highly useful item. Then change how many leading results count. The arrows move the actual items, not their grades.</p><button class="small-button" id="eval-reset" type="button">Reset order</button></div>`,true)+`<div class="section-head"><h2>What each measurement is trying to protect.</h2></div><div class="method-grid"><article class="method"><div class="method-content"><h3 style="margin-top:20px">Do not lose useful candidates.</h3><p>Recall checks how much useful material made it into the inspected list. If a document never enters a shortlist, a reranker restricted to it cannot recover that document.</p><details class="technical-note"><summary>Distinguish two kinds of recall</summary><p><strong>Relevance recall:</strong> recovered relevant documents divided by all relevant documents.</p><p><strong>Neighbor recall:</strong> recovered exact numerical neighbors divided by the number requested. It checks an approximate index, not human usefulness.</p><div class="formula">ANN Recall@k = |approximate top-k ∩ exact vector top-k| / k</div><p>∩ means shared items; vertical bars count them. k is the requested neighbor count.</p></details></div></article><article class="method"><div class="method-content"><h3 style="margin-top:20px">Make the early reading worthwhile.</h3><p>Two lists can contain the same useful pages while putting them in very different positions. Rank-sensitive measures give more credit when useful results appear early.</p><details class="technical-note"><summary>Define the gains and discounts</summary><p>For grade g, this lab gives gain 2^g−1: grades 0,1,2,3 get 0,1,3,7. At position i, divide by log₂(i+1), so later results earn less. DCG adds these discounted gains.</p><div class="formula">DCG@k = Σpositions i≤k (2^gradeᵢ−1)/log₂(i+1)<br>nDCG@k = DCG@k / best_possible_DCG@k</div><p>The best possible value uses the full judged collection sorted by grade. This normalization makes the ideal order score 1. MRR and MAP are averages across queries; this single-query lab reports RR and a stated AP prefix.</p></details></div></article><article class="method"><div class="method-content"><h3 style="margin-top:20px">Compare methods on the same task.</h3><p>Keep the documents, questions, judgments and eligibility rules fixed. Choose settings using a separate practice set, then report results on questions that did not select those settings.</p><p>Also report time, storage and cost. A result from one language or subject may not carry over to another. Repeat measurements across queries rather than trusting one favorable example.</p></div></article><article class="method"><div class="method-content"><h3 style="margin-top:20px">Check what the number leaves out.</h3><p>A related page may lack the evidence needed to answer. Five near-duplicate passages can look like five hits while covering only one point. A useful new source can be mislabeled when judgments are incomplete.</p><p>Check source support, missing aspects and answer faithfulness separately. BEIR compares transfer across domains; BRIGHT and BRIGHT-Pro study harder relevance and complementary evidence.</p></div></article></div>${sourceLine(['eval','beir','bright','brightpro'])}${corpus()}<div class="quiz"><h3>Check your intuition.</h3><p>A relevant document is absent from the top-100 candidate set. Can a reranker restricted to those 100 documents move it to rank 1?</p><button type="button" class="small-button" data-quiz="wrong">Yes, with a stronger model</button><button type="button" class="small-button" data-quiz="right">No, change the candidate set</button><div class="quiz-answer" id="quiz-answer" aria-live="polite"></div></div>`;}
function library(){const kinds=[...new Set(DATA.sources.map(s=>s.kind))],cats=[...new Set(DATA.sources.map(s=>s.category))].sort();return heading('THE READING ROOM','Follow the trail back to the papers.','Foundations, landmarks and useful perspectives.','Use a chapter’s explanation first, then follow its sources when you want more detail. A paper presents a particular research contribution; a survey compares a wider family of work; a book chapter teaches foundations; a practical guide shows how a system is used. Each note below says why that source is worth opening.','Checked '+DATA.checked)+`<div class="reading-path"><div><span class="eyebrow">01 / FOUNDATIONS</span><h3>Learn the vocabulary.</h3>${['boolean','vsm','bm25'].map(id=>`<a href="${SOURCES[id].url}" target="_blank" rel="noopener">${SOURCES[id].title} ↗</a>`).join('')}</div><div><span class="eyebrow">02 / MODERN RETRIEVAL</span><h3>Compare ways to describe a page.</h3>${['dpr','splade','colbert'].map(id=>`<a href="${SOURCES[id].url}" target="_blank" rel="noopener">${SOURCES[id].title.split(':')[0]} ↗</a>`).join('')}</div><div><span class="eyebrow">03 / SYSTEMS & FRONTIERS</span><h3>Question the pipeline.</h3>${['rrf','bright','brightpro'].map(id=>`<a href="${SOURCES[id].url}" target="_blank" rel="noopener">${SOURCES[id].title.split(':')[0]} ↗</a>`).join('')}</div></div><div class="library-filters"><label for="paper-search">SEARCH TITLES, AUTHORS OR NOTES<input type="search" id="paper-search" placeholder="Try: fusion, reasoning, sparse…"></label><label for="paper-kind">SOURCE TYPE<select id="paper-kind"><option value="all">All source types</option>${kinds.map(k=>`<option>${k}</option>`).join('')}</select></label><label for="paper-category">SUBJECT<select id="paper-category"><option value="all">All subjects</option>${cats.map(k=>`<option>${k}</option>`).join('')}</select></label></div><p class="library-count" id="paper-count" aria-live="polite"></p><div id="paper-list"></div><div class="note warm">This is a curated research snapshot, not an exhaustive bibliography or live leaderboard. A historical claim of state-of-the-art performance applies to its paper’s task, date and evaluation protocol. No numbers in the teaching labs are measured model results.</div>`;}
$('#main').innerHTML=panel('overview',overview())+panel('timeline',timeline())+DATA.categories.map((c,i)=>panel(c.id,categoryPanel(c,i))).join('')+panel('evaluation',evaluation())+panel('sources',library());

let activeTab='overview';
function navigate(id,{focus=false,scroll=true}={}){if(!TABLIST.some(x=>x[0]===id))id='overview';activeTab=id;$$('[role=tab]').forEach(t=>{let on=t.dataset.tab===id;t.setAttribute('aria-selected',String(on));t.tabIndex=on?0:-1;});$$('.panel').forEach(p=>p.hidden=p.id!=='panel-'+id);$('#menu-toggle').setAttribute('aria-expanded','false');$('.sidebar').classList.remove('menu-open');$('#menu-toggle').innerHTML=`${esc(TABLIST.find(x=>x[0]===id)[1])}<span aria-hidden="true">＋</span>`;if(focus)$('#tab-'+id).focus();if(scroll)window.scrollTo({top:0,behavior:'instant'});document.title=TABLIST.find(x=>x[0]===id)[1]+' — The Retrieval Atlas';}
$('#tabs').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b){location.hash=b.dataset.tab;}});
$('#tabs').addEventListener('keydown',e=>{if(!e.target.matches('[role=tab]'))return;let i=TABLIST.findIndex(x=>x[0]===activeTab);if(['ArrowDown','ArrowRight'].includes(e.key))i=(i+1)%TABLIST.length;else if(['ArrowUp','ArrowLeft'].includes(e.key))i=(i-1+TABLIST.length)%TABLIST.length;else if(e.key==='Home')i=0;else if(e.key==='End')i=TABLIST.length-1;else return;e.preventDefault();history.replaceState(null,'','#'+TABLIST[i][0]);navigate(TABLIST[i][0],{focus:true});});
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));
$('#menu-toggle').addEventListener('click',()=>{const on=$('.sidebar').classList.toggle('menu-open');$('#menu-toggle').setAttribute('aria-expanded',String(on));});
document.addEventListener('click',e=>{let jump=e.target.closest('[data-go-lab]');if(jump){$('#lab-'+jump.dataset.goLab).scrollIntoView({block:'start'});}let b=e.target.closest('[data-expand]');if(b){let notes=$$('.method', $('#panel-'+b.dataset.expand)),open=notes.some(n=>!n.open);notes.forEach(n=>n.open=open);b.textContent=open?'Collapse all notes':'Expand all notes';}let preset=e.target.closest('[data-bool]');if(preset){$('#bool-query').value=preset.dataset.bool;updateBoolean();}let q=e.target.closest('[data-quiz]');if(q){$('#quiz-answer').textContent=q.dataset.quiz==='right'?'Correct. Improve recall through retrieval, expansion, another source or a deeper candidate budget. Reranking only changes the supplied order.':'A stronger model can reorder only its supplied candidates. The missing document first needs to enter the candidate set.';}});
let printState=[],printFilters=null;
window.addEventListener('beforeprint',()=>{if(printFilters)return;printState=$$('details').map(d=>[d,d.open]);printFilters={era:eraFilter,selection:timelineSelection,query:val('paper-search'),kind:val('paper-kind'),category:val('paper-category'),timelineOpen:!!$('#timeline-detail .technical-note')?.open};renderTimeline('all',0);$('#paper-search').value='';$('#paper-kind').value='all';$('#paper-category').value='all';renderPapers();$$('details').forEach(d=>d.open=true);});
window.addEventListener('afterprint',()=>{printState.forEach(([d,v])=>d.open=v);if(printFilters){renderTimeline(printFilters.era,printFilters.selection);if($('#timeline-detail .technical-note'))$('#timeline-detail .technical-note').open=printFilters.timelineOpen;$('#paper-search').value=printFilters.query;$('#paper-kind').value=printFilters.kind;$('#paper-category').value=printFilters.category;renderPapers();printFilters=null;}});$('#print-guide').addEventListener('click',()=>window.print());

function bind(ids,fn){ids.forEach(id=>$('#'+id).addEventListener('input',()=>{let o=$('#'+id+'-value');if(o)o.textContent=val(id);fn();}));fn();}
function bm25(query,k1=1.2,b=.75){return DOCS.map(d=>({d,score:bm25Parts(d,query,k1,b).reduce((s,p)=>s+p.contribution,0)})).sort((a,b)=>b.score-a.score||a.d.id.localeCompare(b.d.id));}
function lexical(query,mode='cosine'){const qt=typeof query==='string'?tokenize(query).reduce((a,t)=>(a[t]=(a[t]||0)+1,a),{}):query;const terms=[...new Set([...vocab,...Object.keys(qt)])];const q=terms.map(t=>(qt[t]||0)*idf(t));return DOCS.map(d=>{let v=terms.map(t=>(d.tf[t]||0)*idf(t));return {d,score:mode==='cosine'?cosine(q,v):dot(q,v)};}).sort((a,b)=>b.score-a.score||a.d.id.localeCompare(b.d.id));}
function booleanAST(query){const re=/\s*("[^"]*"|\(|\)|[a-zA-Z0-9_-]+)/y;let pos=0,tokens=[],m;while(pos<query.length){if(!query.slice(pos).trim())break;re.lastIndex=pos;m=re.exec(query);if(!m)throw Error('Unsupported character or an unclosed quote near “'+query.slice(pos,pos+16)+'”.');tokens.push(m[1]);pos=re.lastIndex;}if(!tokens.length)throw Error('Enter a term or Boolean expression.');let i=0;function atom(){const t=tokens[i++];if(!t)throw Error('Expected a term.');if(t==='NOT')return {op:'NOT',a:atom()};if(t==='('){const x=or();if(tokens[i++]!==')')throw Error('Close the parenthesis.');return x;}if(['AND','OR',')'].includes(t))throw Error('Expected a term before '+t+'.');if(!t.startsWith('"')&&(tokenize(t).length!==1||tokenize(t)[0]!==t.toLowerCase()))throw Error('This input splits into multiple indexed tokens. Use explicit AND/OR, or put the phrase in quotes.');return {op:'TERM',term:t};}function and(){let a=atom();while(tokens[i]==='AND'){i++;a={op:'AND',a,b:atom()};}return a;}function or(){let a=and();while(tokens[i]==='OR'){i++;a={op:'OR',a,b:and()};}return a;}let ast=or();if(i!==tokens.length)throw Error('Use explicit AND or OR between terms. Operators must be uppercase.');return ast;}
function matchAST(ast,d){if(ast.op==='AND')return matchAST(ast.a,d)&&matchAST(ast.b,d);if(ast.op==='OR')return matchAST(ast.a,d)||matchAST(ast.b,d);if(ast.op==='NOT')return !matchAST(ast.a,d);if(ast.term.startsWith('"')){const ts=tokenize(ast.term);return ts.length>0&&d.tokens.some((_,i)=>ts.every((t,j)=>d.tokens[i+j]===t));}return !!d.tf[ast.term.toLowerCase()];}
function updateBoolean(){try{let ast=booleanAST(val('bool-query')),terms=astTerms(ast),matches=DOCS.filter(d=>matchAST(ast,d)),filtered=matches.filter(d=>!checked('bool-filter')||(d.type==='report'&&d.year>=2020));$('#boolean-result').innerHTML=`<h3>${filtered.length} documents satisfy the rule.</h3><p class="evidence-explainer"><strong>There are no relevance scores in this lab.</strong> This is a pass/fail test on the body text below. The title may use different wording. Query-token occurrences are highlighted so you can check the rule yourself, including excluded words after NOT.</p><div class="formula">${esc(val('bool-query'))}${checked('bool-filter')?' AND [type=report, year≥2020]':''}</div><div class="table-wrap"><table class="mini-table boolean-evidence"><thead><tr><th>Document and actual searched body</th><th>Decision</th></tr></thead><tbody>${DOCS.map(d=>{let hit=matches.includes(d),eligible=!checked('bool-filter')||(d.type==='report'&&d.year>=2020),counts=terms.map(t=>`${t} ×${d.tf[t]||0}`).join(' · ');return `<tr data-document-id="${d.id}"><td><strong>${d.id}</strong><span class="display-title">Display title: ${esc(d.title)}</span><span class="searched-body">${bodyEvidence(d,terms)}</span><span class="token-counts">Body occurrences: ${esc(counts)}</span></td><td><span class="status ${hit&&eligible?'':'bad'}">${hit&&eligible?'KEEP':'SKIP'}</span><small>${!hit?'Word rule fails':!eligible?'Metadata filter fails':'Rule and filter pass'}</small></td></tr>`;}).join('')}</tbody></table></div><p>D1’s title says “Batteries”, but its body contains the exact token battery twice. Searching for batteries returns no bodies in this collection. Lowercasing does not remove the plural ending.</p>`;}catch(e){$('#boolean-result').innerHTML=`<h3>Check the expression.</h3><p>${esc(e.message)}</p>`;}}
function updateLexical(){const q=val('lex-query'),terms=[...new Set(tokenize(q))],mode=val('lex-mode'),res=lexical(q,mode),matches=res.filter(x=>x.score>0);$('#lexical-result').innerHTML=`<h3>${mode==='cosine'?'Compare the proportions of word evidence.':'Add the raw shared-word evidence.'}</h3><p>Rank is the position at left. Score is the number at right. Only exact body-token overlap contributes; the displayed title does not. The highest displayed score sets the bar width, so the bar itself is not a probability.</p>${rows(matches)}<div class="table-wrap"><table class="mini-table"><thead><tr><th>Query token</th><th>Documents containing it</th><th>Rarity weight · IDF</th></tr></thead><tbody>${terms.map(t=>`<tr><td>${esc(t)}</td><td>${df(t)} / 8</td><td>${num(idf(t))}</td></tr>`).join('')}</tbody></table></div>${matches.length?lexicalTrace(q,mode,matches[0].d):''}<p>The weight used is ln((8+1)/(df+1))+1, multiplied by within-document count. Cosine additionally divides the raw product sum by both numerical vector lengths. It accounts for every vocabulary dimension, including non-query words.</p>`;}
function queryLikelihood(query,mu){const terms=tokenize(query),total=DOCS.reduce((s,d)=>s+d.tokens.length,0);return DOCS.map(d=>({d,score:terms.reduce((s,t)=>{const count=DOCS.reduce((n,x)=>n+(x.tf[t]||0),0),p=((d.tf[t]||0)+mu*count/total)/(d.tokens.length+mu);return s+Math.log(p);},0)})).sort((a,b)=>b.score-a.score||a.d.id.localeCompare(b.d.id));}
function updateBM(){let q=val('bm-query'),terms=tokenize(q),mode=val('bm-mode'),res;if(mode==='bm25')res=bm25(q,number('bm-k1'),number('bm-b'));else res=queryLikelihood(q,number('lm-mu'));['bm-k1','bm-b'].forEach(id=>$('#'+id).disabled=mode!=='bm25');$('#lm-mu').disabled=mode!=='lm';if(!terms.length){$('#probabilistic-result').innerHTML='<h3>Enter a query.</h3>';return;}if(mode==='lm'&&terms.some(t=>!df(t))){$('#probabilistic-result').innerHTML='<h3>A query word is absent from the collection.</h3><p>Even the background collection assigns that word zero probability. Multiplying by zero gives query likelihood zero for every document, or log likelihood −∞. This lab does not invent an unknown-word probability. Try words present in the shown bodies.</p>';return;}let matches=res.filter(x=>x.score>0),list=mode==='bm25'?rows(matches):rows(res.map(x=>({...x,score:Math.exp(x.score/terms.length)})),4);$('#probabilistic-result').innerHTML=`<h3>${mode==='bm25'?'More mentions help, with diminishing credit.':'How readily would this page produce the query words?'}</h3><p>${mode==='bm25'?'The numbers are ordering scores, not probabilities. Counts come from bodies only; battery and batteries remain different.':'For readable bars, show the geometric mean query-token probability, calculated by undoing the average log likelihood. For this fixed query it gives the same order as the full likelihood.'}</p>${list}<div class="formula">8 documents · average body length ${num(avgdl,3)} tokens<br>${mode==='bm25'?`Repetition setting k₁=${val('bm-k1')} · length setting b=${val('bm-b')}`:`Background strength μ=${val('lm-mu')}`}</div>${mode==='bm25'?(matches.length?bmTrace(matches[0].d,q,number('bm-k1'),number('bm-b')):''):likelihoodTrace(res[0].d,q,number('lm-mu'))}<p>${mode==='bm25'?'Compare short D1 with long D6. Set b=0 to remove the length adjustment. The lab uses the stated positive-IDF BM25 variant and counts each distinct query token once.':'The model multiplies evidence for query-token occurrences. A repeated query token is counted again. Smoothing can give a nonzero probability to a token absent from this page if it occurs elsewhere in the collection.'}</p>`;}
function updateExpansion(){const mode=val('exp-mode'),w=number('exp-weight'),q={power:1,after:1,sunset:1};let extra={},description='Original words alone have no literal overlap with these body tokens.';if(mode==='synonym'){extra={electricity:w,night:w};description='Controlled mappings: power → electricity; sunset → night. These are context-specific examples, not universal synonyms.';}if(mode==='pseudo'){const initial=lexical({power:1,after:1,sunset:1,electricity:1},'cosine'),top=initial[0].d;extra=Object.fromEntries([...new Set(top.tokens)].filter(t=>!q[t]).slice(0,5).map(t=>[t,w]));description=`A preliminary controlled expansion adds “electricity”, then the top document ${top.id} supplies its first five new unique tokens. This toy rule illustrates pseudo-feedback, not RM3.`;}if(mode==='hyde'){extra={solar:w,battery:w,storage:w,electricity:w,night:w};description='Fixed hypothesis: “Solar battery storage saves electricity for night.” The demo searches its weighted tokens lexically; actual HyDE encodes a generated document with a dense model.';}const weighted={...q,...extra},res=lexical(weighted).filter(x=>x.score>0);$('#expansion-result').innerHTML=`<h3>${res.length?res.length+' documents become reachable.':'The vocabulary gap is visible.'}</h3><div class="tile-row">${Object.entries(weighted).filter(([t,v])=>v>0).map(([t,v])=>`<span class="term-tile">${esc(t)} · ${num(v,1)}</span>`).join('')}</div>${rows(res)}<p>${description}</p><p>The order is calculated by counting shared words, giving rarer words more influence, and comparing the proportions of these weighted lists. This is TF–IDF cosine, developed in the word-importance chapter. The lab compares these particular reformulations, not the measured performance of the cited algorithms.</p>`;}
const denseVectors=[{id:'A',label:'A · grid storage',v:[.95,.2]},{id:'B',label:'B · electric car',v:[.65,.85]},{id:'C',label:'C · overnight electricity',v:[.85,.1]},{id:'D',label:'D · transport policy',v:[.1,.95]}];
function updateDense(){const θ=number('dense-angle')*Math.PI/180,q=[Math.cos(θ),Math.sin(θ)],metric=val('dense-metric'),points=denseVectors.map(x=>({...x,v:x.v.map(v=>v*(x.id==='B'&&checked('dense-scale')?3:1))})),ranked=points.map(x=>({label:x.label,score:metric==='dot'?dot(q,x.v):cosine(q,x.v),sub:`number list [${x.v.map(v=>num(v,2)).join(', ')}]`})).sort((a,b)=>b.score-a.score);$('#dense-result').innerHTML=`<h3>${metric==='dot'?'Stretching a list can change its score.':'Direction matters; stretching alone does not.'}</h3><svg class="geom" viewBox="0 0 310 235" role="img" aria-label="Two-dimensional numerical map with equal scales on both axes"><path d="M42 190H253 M42 190V20" stroke="#9daf9d" fill="none"/><text x="101" y="220" font-size="10" fill="#657278">energy-storage axis →</text><text x="5" y="12" font-size="10" fill="#657278">transport ↑</text><text x="30" y="203" font-size="9" fill="#657278">0</text><text x="198" y="203" font-size="9" fill="#657278">1</text><text x="27" y="34" font-size="9" fill="#657278">1</text>${denseVectors.map(x=>`<circle cx="${42+x.v[0]*160}" cy="${190-x.v[1]*160}" r="5" fill="#8ab29c"/><text x="${49+x.v[0]*160}" y="${196-x.v[1]*160}" font-size="10" fill="#315a4b">${x.id}</text>`).join('')}<path d="M42 190L${42+q[0]*160} ${190-q[1]*160}" stroke="#ba583c" stroke-width="2"/><circle cx="${42+q[0]*160}" cy="${190-q[1]*160}" r="5" fill="#ba583c"/><text x="${47+q[0]*160}" y="${181-q[1]*160}" font-size="10" fill="#ba583c">request q</text></svg>${rows(ranked)}<p>The map uses equal numerical scales on its axes. To keep it visible when you stretch B, the map always shows the original document coordinates. The list above shows the actual scored coordinates, including any 3× scaling.</p><details class="calculation-trace"><summary>Follow the number-list comparison</summary><p>Let θ be the direction slider, in degrees. The request list is q=[cos θ, sin θ], a point one unit from the origin. Here q=[${q.map(v=>num(v,6)).join(', ')}].</p><div class="formula">Dot product: multiply matching entries and add.<br>Cosine: divide that dot product by both vector lengths.<br>For the winning item: ${num(ranked[0].score,6)}.</div><p>Vector length is the square root of the sum of squared entries. Real learned embeddings have many dimensions and do not usually have simple named axes.</p></details>`;}
function updateSparse(){let x=number('sparse-expansion'),threshold=number('sparse-threshold'),raw={renewable:1,storage:1,battery:.9*x,solar:.75*x,grid:.45*x},q=Object.fromEntries(Object.entries(raw).map(([t,w])=>[t,w>=threshold?w:0])),documents=[{label:'A · battery + grid',v:{battery:1,grid:.8}},{label:'B · renewable policy',v:{renewable:.7,policy:1}},{label:'C · general storage',v:{storage:.55}},{label:'D · solar electricity',v:{solar:.9,electricity:.8}}],res=documents.map(d=>({label:d.label,score:Object.entries(q).reduce((s,[t,v])=>s+v*(d.v[t]||0),0),sub:Object.entries(d.v).map(([t,v])=>`${t}=${v}`).join(', ')})).sort((a,b)=>b.score-a.score);$('#sparse-result').innerHTML=`<h3>${Object.values(q).filter(w=>w>0).length} nonzero word clues.</h3><div class="tile-row">${Object.entries(raw).map(([t,w])=>`<span class="term-tile ${!q[t]?'off':''}">${t} · ${num(w,2)}</span>`).join('')}</div>${rows(res)}<div class="formula">score(A) = ${num(q.battery)} × 1 + ${num(q.grid)} × .8 = ${num(res.find(d=>d.label.startsWith('A')).score)}</div><p>Query and document weights are visible teaching fixtures. The browser drops query weights below the threshold, then multiplies weights of shared words and adds them (a sparse dot product). It does not run SPLADE or learn weights.</p>`;}
const lateMatrices={balanced:{tokens:['solar','cells','battery'],matrix:[[.9,.65,.25],[.2,.3,.8]]},one:{tokens:['solar','roof','cost'],matrix:[[.98,.6,.25],[.12,.1,.18]]},duplicate:{tokens:['solar','battery','battery'],matrix:[[.9,.25,.25],[.2,.8,.8]]}};
function updateLate(){let {tokens,matrix}=lateMatrices[val('late-doc')],qs=checked('late-storage')?['solar','storage']:['solar'],sums=qs.map((_,i)=>Math.max(...matrix[i])),score=sums.reduce((a,b)=>a+b,0);$('#late-result').innerHTML=`<h3>MaxSim = ${num(score,2)}</h3><div class="table-wrap"><table class="mini-table matrix"><thead><tr><th>query ↓ / document →</th>${tokens.map(t=>`<th>${t}</th>`).join('')}<th>max</th></tr></thead><tbody>${qs.map((q,i)=>`<tr><th>${q}</th>${matrix[i].map(v=>`<td class="${v===sums[i]?'max':''}">${num(v,2)}</td>`).join('')}<td class="max">${num(sums[i],2)}</td></tr>`).join('')}</tbody></table></div><div class="formula">${sums.map(v=>num(v,2)).join(' + ')} = ${num(score,2)}</div><p>Each query token chooses its best support independently. Ties are highlighted together, but each row contributes its maximum only once. A document token can be reused for several query tokens; this is not a one-to-one matching problem.</p>`;}
const ivfClusters=[{id:'A',c:[.3,.25],points:[{id:'A1',v:[.24,.3]},{id:'A2',v:[.44,.47]}]},{id:'B',c:[.7,.65],points:[{id:'B1',v:[.54,.5]},{id:'B2',v:[.77,.8]}]},{id:'C',c:[.2,.85],points:[{id:'C1',v:[.3,.85]},{id:'C2',v:[.12,.9]}]}];
const distance=(a,b)=>Math.hypot(a[0]-b[0],a[1]-b[1]);
function ivfResults(n,y){let q=[.5,y],clusters=[...ivfClusters].sort((a,b)=>distance(q,a.c)-distance(q,b.c)),visited=clusters.slice(0,n),all=ivfClusters.flatMap(c=>c.points),exact=[...all].sort((a,b)=>distance(q,a.v)-distance(q,b.v)).slice(0,2),approx=visited.flatMap(c=>c.points).sort((a,b)=>distance(q,a.v)-distance(q,b.v)).slice(0,2);return{q,visited,all,exact,approx,recall:approx.filter(d=>exact.some(x=>x.id===d.id)).length/2};}
function updateIVF(){let r=ivfResults(number('ivf-probe'),number('ivf-y')),map=v=>[25+v[0]*310,180-v[1]*165];$('#indexes-result').innerHTML=`<h3>${r.visited.length} of 3 clusters searched.</h3><svg class="geom" viewBox="0 0 360 205" role="img" aria-label="IVF-style cluster probing, with centroids, document points and query"><path d="M25 15V180H345" stroke="#b5c7b5" fill="none"/>${ivfClusters.map(c=>{let [x,y]=map(c.c),on=r.visited.includes(c);return `<circle cx="${x}" cy="${y}" r="49" fill="${on?'#d9e7d6':'#efeee7'}" stroke="${on?'#a9c8af':'#dedfd8'}"/><path d="M${x-4} ${y-4}l8 8m-8 0l8-8" stroke="#657278"/><text x="${x+7}" y="${y-7}" fill="#657278" font-size="9">center ${c.id}</text>${c.points.map(p=>{let [px,py]=map(p.v);return `<circle cx="${px}" cy="${py}" r="4" fill="${on?'#087a72':'#aab6aa'}"/><text x="${px+6}" y="${py+5}" font-size="9" fill="#315a4b">${p.id}</text>`;}).join('')}`;}).join('')}<circle cx="${map(r.q)[0]}" cy="${map(r.q)[1]}" r="5" fill="#ba583c"/><text x="${map(r.q)[0]+7}" y="${map(r.q)[1]+3}" font-size="10" fill="#ba583c">query</text></svg>${metrics([[num(r.recall*100,0)+'%','ANN Recall@2'],[r.visited.length*2+'/6','document distances'],['2','returned items']])}<div class="formula">Exact top-2: ${r.exact.map(x=>x.id).join(', ')}<br>Probed top-2: ${r.approx.map(x=>x.id).join(', ')}</div><p>Query=[.50, ${num(r.q[1],2)}]. Cluster assignments are fixed teaching data. Work shown counts only document distances, excluding the three group-center comparisons. More probes reach the exact scan when all three are searched.</p>`;$('#indexes-result').innerHTML+=`<details class="calculation-trace"><summary>Check every point’s straight-line distance</summary><p>Square the horizontal difference, square the vertical difference, add them, then take the square root. Visiting a group makes its points eligible; only the nearest two eligible points are returned.</p><div class="table-wrap"><table class="mini-table"><thead><tr><th>Point</th><th>Coordinates</th><th>Distance to query</th><th>Group visited?</th></tr></thead><tbody>${r.all.map(p=>{let group=ivfClusters.find(c=>c.points.some(x=>x.id===p.id));return `<tr><td>${p.id}</td><td>[${p.v.join(', ')}]</td><td>${num(distance(r.q,p.v),6)}</td><td>${r.visited.includes(group)?'yes':'no'}</td></tr>`;}).join('')}</tbody></table></div><p>Shaded circles identify groups schematically; they are not exact partition boundaries. Numerical calculations use the fixed point assignments, not the circle outlines.</p></details>`;}
const semantic=[.91,.98,.2,.6,.08,.8,.72,.03];
const rerankScores=[.96,.99,.08,.52,.03,.83,.6,.01];
function updateRanking(){const depth=number('rerank-depth'),hybrid=val('rerank-source')==='hybrid',pool=hybrid?fusionResults(8,60,.5).ranked:bm25('solar battery storage').filter(x=>x.score>0),retrieved=pool.slice(0,depth),ranked=checked('rerank-on')?retrieved.map(x=>({...x,score:rerankScores[DOCS.indexOf(x.d)]})).sort((a,b)=>b.score-a.score||a.d.id.localeCompare(b.d.id)):retrieved,rel=retrieved.filter(x=>x.d.rel>0).length;$('#ranking-result').innerHTML=`<h3>${checked('rerank-on')?'Same candidates. A new order.':'The first-stage order.'}</h3>${rows(ranked)}${metrics([[retrieved.length,'actual candidates scored'],[num(rel/5*100,0)+'%','useful-document recall'],[retrieved.some(x=>x.d.id==='D2')?'IN':'OUT','D2 in shortlist']])}<div class="formula">Requested budget: up to ${depth}<br>Source: ${hybrid?'word + illustrative meaning lists':'positive BM25 body-token matches only'}<br>Source order: ${retrieved.map(x=>x.d.id).join(' → ')}</div><p>${hybrid?'D2 enters through the illustrative meaning list. Its word score remains exactly zero. The hybrid order is calculated weighted RRF with k=60 and weights .5/.5.':'There are only 7 positive word matches. Raising the budget to 8 still returns 7, and D2 remains out. This lab never pads the word-only shortlist with zero-score documents.'}</p><p>The second-stage numbers are fixed teaching scores, not a running neural model or relevance probabilities. Without the reranker, the displayed scale is the selected source’s own score scale.</p>`;}
function minmax(items){const vs=items.map(x=>x.score),lo=Math.min(...vs),hi=Math.max(...vs);return Object.fromEntries(items.map(x=>[x.d.id,hi===lo?0:(x.score-lo)/(hi-lo)]));}
function fusionResults(depth,k,alpha,duplicate=false,mode='rrf'){let a=bm25('solar battery storage').filter(x=>x.score>0).slice(0,depth),b=DOCS.map((d,i)=>({d,score:semantic[i]})).sort((a,b)=>b.score-a.score).slice(0,depth),ids=[...new Set([...a,...b].map(x=>x.d.id))],na=minmax(a),nb=minmax(b);let ranked=ids.map(id=>{const ar=a.findIndex(x=>x.d.id===id),br=b.findIndex(x=>x.d.id===id),ac=ar<0?0:alpha/(k+ar+1),bc=br<0?0:(1-alpha)/(k+br+1);return{d:DOCS.find(d=>d.id===id),ar:ar<0?null:ar+1,br:br<0?null:br+1,ac,bc,score:mode==='score'?(alpha*(na[id]||0)*(duplicate?2:1)+(1-alpha)*(nb[id]||0)):(ac*(duplicate?2:1)+bc)};}).sort((x,y)=>y.score-x.score||x.d.id.localeCompare(y.d.id));return{a,b,ranked};}
function mmrSelect(items,lambda){const max=Math.max(...items.map(x=>x.score),.00001),remaining=items.map(x=>({...x,relevance:x.score/max})),selected=[];while(remaining.length){remaining.forEach(x=>{x.redundancy=selected.length?Math.max(...selected.map(y=>{let xs=new Set(x.d.tokens),ys=new Set(y.d.tokens),union=new Set([...xs,...ys]);return [...xs].filter(t=>ys.has(t)).length/union.size;})):0;x.mmr=lambda*x.relevance-(1-lambda)*x.redundancy;});remaining.sort((a,b)=>b.mmr-a.mmr||b.relevance-a.relevance||a.d.id.localeCompare(b.d.id));selected.push(remaining.shift());}return selected;}
function updateFusion(){let mode=val('fusion-mode'),depth=number('fusion-depth'),alpha=number('fusion-alpha'),k=number('fusion-k'),dup=checked('fusion-duplicate'),r=fusionResults(depth,k,mode==='mmr'?.5:alpha,dup,mode);$('#fusion-k').disabled=mode==='score';let ranked=mode==='mmr'?mmrSelect(r.ranked,alpha):r.ranked;$('#fusion-result').innerHTML=`<h3>${mode==='rrf'?'Rank positions become votes.':mode==='score'?'Scale first. Then blend.':'Prefer useful, complementary evidence.'}</h3><div class="formula">Lexical: ${r.a.map(x=>x.d.id).join(' → ')}<br>Semantic: ${r.b.map(x=>x.d.id).join(' → ')}${dup?'<br>+ a second copy of the lexical list':''}</div><div class="table-wrap"><table class="mini-table"><thead><tr><th>Item</th><th>Lex rank</th><th>Sem rank</th><th>${mode==='mmr'?'MMR at selection':'Fused score'}</th></tr></thead><tbody>${ranked.map(x=>`<tr><td>${x.d.id} · ${esc(x.d.title)}</td><td>${x.ar||'—'}</td><td>${x.br||'—'}</td><td class="hit">${num(mode==='mmr'?x.mmr:x.score,5)}</td></tr>`).join('')}</tbody></table></div>${mode==='rrf'&&ranked.length?`<div class="formula">${ranked[0].d.id}: lexical ${num(ranked[0].ac,5)}${dup?' × 2':''} + semantic ${num(ranked[0].bc,5)} = ${num(ranked[0].score,5)}</div>`:''}<p>${mode==='rrf'?`α=${num(alpha,2)}, k=${k}. Absent items contribute zero. Repeated document IDs are combined into one row. Equal scores use document-ID order. A duplicate source adds another vote; it is not independent evidence.`:mode==='score'?'Within each chosen list, map the smallest score to 0 and the largest to 1, then blend: this is min–max normalization. A constant or one-item list maps to all zeros by this stated convention; missing documents also contribute 0. Changing the result depth changes the scale. With one-item lists this convention erases both scores, illustrating why the normalization choice matters. These values are not calibrated probabilities.':`MMR uses equal-weight RRF (k=${k}) normalized by its maximum as relevance. Redundancy is shared distinct body tokens divided by distinct body tokens in either document (Jaccard similarity). The empty selected set has redundancy 0; ties prefer higher relevance, then ID. Negative MMR values can occur.`}</p>`;}
function updateGraph(){let mode=val('graph-mode'),edge=checked('graph-edge'),two=mode==='two',summary=mode==='summary';$('#structured-result').innerHTML=`<h3>${summary?'Overview plus source pointers.':two?'Two links connect the answer.':'The first hop finds a product.'}</h3><svg class="geom" viewBox="0 0 370 125" role="img" aria-label="Synthetic graph: Aurora makes Cell A, Cell A uses sodium"><rect x="5" y="28" width="95" height="45" rx="6" fill="#e2eadd" stroke="#bad1bb"/><text x="52" y="55" text-anchor="middle" font-size="13" fill="#203439">Aurora</text><path d="M100 50H140" stroke="#087a72"/><text x="120" y="40" text-anchor="middle" font-size="9" fill="#657278">makes</text><rect x="140" y="28" width="90" height="45" rx="6" fill="#e2eadd" stroke="#bad1bb"/><text x="185" y="55" text-anchor="middle" font-size="13" fill="#203439">Cell A</text><path d="M230 50H270" stroke="${edge?'#087a72':'#c8c9bd'}" stroke-dasharray="${edge?'0':'4 4'}"/><text x="250" y="40" text-anchor="middle" font-size="9" fill="#657278">uses</text><rect x="270" y="28" width="95" height="45" rx="6" fill="${edge?'#f5e8dd':'#efeee7'}" stroke="#d8cdbb"/><text x="317" y="55" text-anchor="middle" font-size="13" fill="#203439">sodium</text><text x="53" y="100" text-anchor="middle" font-size="8" fill="#657278">entity</text><text x="185" y="100" text-anchor="middle" font-size="8" fill="#657278">evidence E1</text><text x="317" y="100" text-anchor="middle" font-size="8" fill="#657278">evidence E2</text></svg><div class="formula">${summary?(edge?'Community note: Aurora’s Cell A uses sodium. Sources: E1 + E2.':'Community note: Aurora makes Cell A. Material evidence is missing; do not assert sodium.'):(two?(edge?'Aurora → Cell A → sodium<br>Answer supported by E1 + E2.':'Aurora → Cell A → [missing edge]<br>No supported material answer.'):'Aurora → Cell A<br>Product found; material still unresolved.')}</div><p>Graph records and company names are invented for teaching. The path is deterministic. If evidence E2 is unavailable, the summary is also restricted; a prior summary must not masquerade as fresh source evidence.</p>`;}
function updateVisual(){let mode=val('visual-mode'),table=val('visual-query')==='table',preserved=table?mode!=='text':mode==='visual';$('#multimodal-result').innerHTML=`<h3>${preserved?'The needed relationship is retained.':'The representation loses a clue.'}</h3><svg class="geom" viewBox="0 0 355 215" role="img" aria-label="Synthetic page containing a labeled table and two declining chart curves"><rect x="30" y="8" width="290" height="198" rx="5" fill="#fffefa" stroke="#bac8b9"/><text x="49" y="32" font-family="Georgia" font-size="14" fill="#203439">Storage performance · teaching data</text><path d="M48 44H302 M48 68H302 M48 91H302 M48 113H302 M137 44V113 M222 44V113" stroke="#d5dfd0"/><text x="52" y="60" font-size="9" fill="#657278">Option</text><text x="147" y="60" font-size="9" fill="#657278">Cost units</text><text x="233" y="60" font-size="9" fill="#657278">Cycles</text><text x="52" y="83" font-size="10" fill="#203439">A</text><text x="153" y="83" font-size="10" fill="#203439">70</text><text x="239" y="83" font-size="10" fill="#203439">1500</text><text x="52" y="106" font-size="10" fill="#203439">B</text><text x="153" y="106" font-size="10" fill="#203439">90</text><text x="239" y="106" font-size="10" fill="#203439">3000</text><path d="M52 126V187H297" stroke="#a7bba7" fill="none"/><path d="M59 133L126 142L199 154L282 166" stroke="#087a72" fill="none" stroke-width="2"/><path d="M59 134L126 150L199 171L282 181" stroke="#ba583c" fill="none" stroke-width="2"/><text x="285" y="166" font-size="9" fill="#087a72">A</text><text x="285" y="182" font-size="9" fill="#ba583c">B</text></svg><div class="formula">${mode==='text'?'Flat token bag: A B 70 90 1500 3000 performance cost cycles':mode==='layout'?'Rows: A → cost 70, cycles 1500<br>B → cost 90, cycles 3000':'Page regions: title + structured table + plotted curves'}</div><p>${table?(preserved?'Row structure associates B with 3000 cycles, supporting the comparison. A text-based pipeline can preserve tables too when parsing succeeds.':'The numbers survive, but this deliberately lossy token bag removes row and column associations. “Text-only” does not have to be this lossy; structured extraction can preserve the answer.'):(preserved?'The orange B curve declines faster in this drawing. Retaining pixels permits visual comparison; a trained model must still learn to interpret them correctly.':'Neither the token bag nor the retained table contains the plotted trajectory. You need the visual region, extracted chart data or a trustworthy description.')}</p><p>All numbers are synthetic. The status above reports information retained by this demonstration’s representation, not a model accuracy measurement.</p>`;}
function updateAgent(){let budget=number('agent-budget'),diverse=checked('agent-diverse'),steps=[['Search 1 · cost','Evidence C1: option A costs less in this invented scenario.','cost']];if(budget>1)steps.push(diverse?['Search 2 · durability','Evidence D1: option B lasts longer under the stated conditions.','durability']:['Search 2 · another cost page','Evidence C2 repeats the first cost comparison.','cost']);if(budget>2)steps.push(diverse?['Search 3 · verify comparability','Evidence V1 states a shared measurement setup.','conditions']:['Search 3 · cost summary','Evidence C3 summarizes the same cost claim.','cost']);let covered=new Set(steps.map(s=>s[2])),aspects=['cost','durability','conditions'],coverage=covered.size/3;$('#frontier-result').innerHTML=`<h3>${num(coverage*100,0)}% of required evidence aspects covered.</h3><div class="frontier-trace">${steps.map(([h,t])=>`<div class="trace-step"><strong>${h}</strong><small>${t}</small></div>`).join('')}</div><div class="tile-row">${aspects.map(a=>`<span class="term-tile ${covered.has(a)?'':'off'}">${a}</span>`).join('')}</div><p><strong>${covered.size===3?'Stop: all three aspects are supported in this trace.':'Unresolved: '+aspects.filter(a=>!covered.has(a)).join(', ')+'.'}</strong> More searches do not guarantee more evidence. This scripted example counts distinct aspects, not the reliability of the claims.</p>`;}
let evalOrder=[];
function evaluationPreset(){const p=val('eval-preset');evalOrder=p==='ideal'?[...DOCS].sort((a,b)=>b.rel-a.rel||a.id.localeCompare(b.id)).map(d=>d.id):p==='reverse'?[...DOCS].sort((a,b)=>a.rel-b.rel||a.id.localeCompare(b.id)).map(d=>d.id):p==='semantic'?DOCS.map((d,i)=>({d,s:semantic[i]})).sort((a,b)=>b.s-a.s).map(x=>x.d.id):bm25('solar battery storage').map(x=>x.d.id);updateEvaluation();}
function calcMetrics(order,k){const docs=order.slice(0,k).map(id=>DOCS.find(d=>d.id===id)),relevant=DOCS.filter(d=>d.rel>0).length,hits=docs.filter(d=>d.rel>0).length,first=docs.findIndex(d=>d.rel>0),dcg=docs.reduce((s,d,i)=>s+(2**d.rel-1)/Math.log2(i+2),0),ideal=[...DOCS].sort((a,b)=>b.rel-a.rel).slice(0,k).reduce((s,d,i)=>s+(2**d.rel-1)/Math.log2(i+2),0);let running=0,ap=docs.reduce((s,d,i)=>{if(d.rel>0){running++;return s+running/(i+1);}return s;},0)/relevant;return{precision:hits/k,recall:hits/relevant,rr:first<0?0:1/(first+1),ndcg:ideal?dcg/ideal:0,ap,dcg,idcg:ideal};}
function updateEvaluation(){let k=number('eval-k'),m=calcMetrics(evalOrder,k),inspected=evalOrder.slice(0,k).map(id=>DOCS.find(d=>d.id===id)),hits=inspected.filter(d=>d.rel>0).length,first=inspected.findIndex(d=>d.rel>0),running=0;$('#evaluation-result').innerHTML=`<p class="evaluation-explanation">Inspect the first <strong>${k}</strong> results. <strong>${hits}</strong> have grade above zero. There are <strong>5</strong> such documents in the full collection. ${first<0?'No relevant result appears within this cutoff.':`The first relevant result is at position <strong>${first+1}</strong>.`}</p>${metrics([[num(m.precision),'Useful among returned · Precision@'+k],[num(m.recall),'Useful recovered · Recall@'+k],[num(m.rr),'First useful position · RR@'+k],[num(m.ndcg),'Graded order vs ideal · nDCG@'+k],[num(m.ap),'Precision credit prefix / all 5 relevant'],[num(m.dcg,2),'Discounted grade credit · DCG@'+k]])}<p class="table-key">The leading position number is rank. The grade is our fixed teaching judgment, not the current search score. Moving a row changes its position, never its grade. Rows after position ${k} are dimmed and do not earn credit in this measurement.</p>${evalOrder.map((id,i)=>{let d=DOCS.find(d=>d.id===id);return `<div class="eval-row" style="${i>=k?'opacity:.48':''}"><span class="rank-pos">${i+1}</span><span>${d.id} · ${esc(d.title)}</span><span class="gain">grade ${d.rel}/3</span><span class="move"><button type="button" data-move="${i}" data-dir="-1" aria-label="Move ${id} up" ${i===0?'disabled':''}>↑</button><button type="button" data-move="${i}" data-dir="1" aria-label="Move ${id} down" ${i===evalOrder.length-1?'disabled':''}>↓</button></span></div>`;}).join('')}<details class="calculation-trace"><summary>Work through the measurements row by row</summary><div class="formula">Precision = ${hits}/${k} = ${num(m.precision,6)}.<br>Recall = ${hits}/5 = ${num(m.recall,6)}.<br>RR = ${first<0?'0 (no relevant item in cutoff)':`1/${first+1} = ${num(m.rr,6)}`}.</div><p>For nDCG, give grades 0,1,2,3 gains 0,1,3,7. Divide each gain by log₂(position+1), then add. Compare this total with the best possible total for the same cutoff.</p><div class="table-wrap"><table class="mini-table"><thead><tr><th>Position / item</th><th>Grade</th><th>Gain</th><th>Discounted gain</th><th>Precision if relevant</th></tr></thead><tbody>${inspected.map((d,i)=>{let gain=2**d.rel-1;if(d.rel>0)running++;return `<tr><td>${i+1} / ${d.id}</td><td>${d.rel}</td><td>${gain}</td><td>${num(gain/Math.log2(i+2),5)}</td><td>${d.rel>0?`${running}/${i+1} = ${num(running/(i+1),5)}`:'not added'}</td></tr>`;}).join('')}</tbody></table></div><div class="formula">DCG=${num(m.dcg,6)}.<br>Ideal DCG=${num(m.idcg,6)}.<br>nDCG=${num(m.dcg,6)}/${num(m.idcg,6)}=${num(m.ndcg,6)}.<br>AP prefix = precision values at relevant ranks≤${k}, added and divided by all 5 relevant documents = ${num(m.ap,6)}.</div><p>At k=8, this AP prefix is ordinary full-list average precision. Some systems use a different truncated-AP denominator; this lab deliberately keeps 5. These are single-query measurements. MRR and MAP require averaging across queries.</p></details>`;}
$('#evaluation-result').addEventListener('click',e=>{let b=e.target.closest('[data-move]');if(!b)return;let i=+b.dataset.move,j=i+(+b.dataset.dir);if(j<0||j>=evalOrder.length)return;[evalOrder[i],evalOrder[j]]=[evalOrder[j],evalOrder[i]];updateEvaluation();const moved=$(`[data-move="${j}"][data-dir="${b.dataset.dir}"]`);if(moved&&!moved.disabled)moved.focus({preventScroll:true});});
$('#eval-preset').addEventListener('input',evaluationPreset);$('#eval-reset').addEventListener('click',evaluationPreset);
let eraFilter='all',timelineSelection=0;
function renderTimeline(filter=eraFilter,selected=timelineSelection){eraFilter=filter;let events=DATA.timeline.map((t,i)=>({...t,index:i})).filter(t=>{let y=parseInt(t.year,10);return filter==='all'||filter==='early'&&y<2000||filter==='middle'&&y>=2000&&y<=2020||filter==='recent'&&y>=2021;});if(!events.some(t=>t.index===selected))selected=events[0].index;timelineSelection=selected;$$('[data-era]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.era===filter)));$('#timeline-list').innerHTML=events.map(t=>`<button class="timeline-event" type="button" data-milestone="${t.index}" aria-pressed="${t.index===selected}"><time>${t.year}</time><span><strong>${esc(t.lesson.title)}</strong><small>${esc(t.title)}</small><span class="print-only">${esc(t.lesson.story)}<br>Source: ${esc(SOURCES[t.source].title)}</span></span></button>`).join('');let t=DATA.timeline[selected],source=SOURCES[t.source];$('#timeline-detail').innerHTML=`<span class="eyebrow">WHAT PROBLEM DID THIS IDEA ADDRESS?</span><div class="big-year">${t.year}</div><h2>${esc(t.lesson.title)}</h2><p class="timeline-explained">${esc(t.lesson.story)}</p><p class="formal-name">Landmark: ${esc(t.title)}</p><details class="technical-note"><summary>Then read the historical and technical context</summary><p>${esc(t.text)}</p></details><div class="source-line">READ THE SOURCE<a href="${source.url}" target="_blank" rel="noopener">${esc(source.title)} ↗</a><span>${esc(source.author)} · ${source.year}</span></div><a class="primary" href="#${t.category}">Explore the idea <span>↗</span></a>`;}
$('#timeline-list').addEventListener('click',e=>{let b=e.target.closest('[data-milestone]');if(b){let i=+b.dataset.milestone;renderTimeline(eraFilter,i);$(`[data-milestone="${i}"]`).focus({preventScroll:true});}});$$('[data-era]').forEach(b=>b.addEventListener('click',()=>renderTimeline(b.dataset.era)));
function renderPapers(){const query=val('paper-search').toLowerCase().trim(),kind=val('paper-kind'),category=val('paper-category'),papers=DATA.sources.filter(s=>(kind==='all'||s.kind===kind)&&(category==='all'||s.category===category)&&`${s.title} ${s.author} ${s.why} ${s.category}`.toLowerCase().includes(query));$('#paper-count').textContent=`${papers.length} of ${DATA.sources.length} references`;$('#paper-list').innerHTML=papers.length?papers.map(s=>`<article class="paper" id="paper-${s.id}"><div class="paper-year">${s.year}</div><div><h3><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a></h3><p class="authors">${esc(s.author)}</p><p>${esc(s.why)}</p><span class="pill">${esc(s.kind)}</span><span class="pill warm">${esc(s.category)}</span></div><a class="paper-open" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer" aria-label="Open ${esc(s.title)}">↗</a></article>`).join(''):'<div class="empty">No sources match. Broaden the search or reset a filter.</div>';}
$('#global-search').addEventListener('input',()=>{const q=val('global-search').trim().toLowerCase(),box=$('#search-results');if(!q){box.hidden=true;box.innerHTML='';return;}let matches=DATA.categories.flatMap(c=>c.methods.map((m,i)=>({...m,category:c.id,categoryName:c.name,index:i}))).filter(m=>`${m.title} ${m.tag} ${m.idea} ${m.example} ${m.lesson.title} ${m.lesson.intuition}`.toLowerCase().includes(q));let papers=DATA.sources.filter(s=>`${s.title} ${s.author} ${s.category}`.toLowerCase().includes(q));box.hidden=false;box.innerHTML=`<p>${matches.length} method notes · ${papers.length} sources</p>${matches.slice(0,5).map(m=>`<button type="button" data-result-cat="${m.category}" data-result-index="${m.index}">${esc(m.title)}<small>${esc(m.categoryName)}</small></button>`).join('')}${papers.slice(0,2).map(s=>`<button type="button" data-result-paper="${s.id}">${esc(s.title)}<small>Paper / reading room</small></button>`).join('')}${!matches.length&&!papers.length?'<p>No matches. Try “fusion” or “feedback”.</p>':''}`;});
$('#search-results').addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.resultCat){const id=b.dataset.resultCat;history.replaceState(null,'','#'+id);navigate(id,{scroll:false});const note=$(`#method-${id}-${b.dataset.resultIndex}`);note.open=true;note.scrollIntoView({block:'start'});$('summary',note).focus({preventScroll:true});}else if(b.dataset.resultPaper){$('#paper-search').value=SOURCES[b.dataset.resultPaper].title;$('#paper-kind').value='all';$('#paper-category').value='all';renderPapers();history.replaceState(null,'','#sources');navigate('sources');$('#paper-search').focus({preventScroll:true});}$('#global-search').value='';$('#search-results').hidden=true;});

bind(['form-query','form-map'],updateWordForms);bind(['bool-query','bool-filter'],updateBoolean);bind(['lex-query','lex-mode'],updateLexical);bind(['bm-query','bm-mode','bm-k1','bm-b','lm-mu'],updateBM);bind(['exp-mode','exp-weight'],updateExpansion);bind(['dense-angle','dense-metric','dense-scale'],updateDense);bind(['sparse-expansion','sparse-threshold'],updateSparse);bind(['late-doc','late-storage'],updateLate);bind(['ivf-probe','ivf-y'],updateIVF);bind(['rerank-depth','rerank-on','rerank-source'],updateRanking);bind(['fusion-mode','fusion-depth','fusion-k','fusion-alpha','fusion-duplicate'],updateFusion);bind(['graph-mode','graph-edge'],updateGraph);bind(['visual-mode','visual-query'],updateVisual);bind(['agent-budget','agent-diverse'],updateAgent);bind(['eval-k'],()=>{if(evalOrder.length)updateEvaluation();});bind(['paper-search','paper-kind','paper-category'],renderPapers);evaluationPreset();renderTimeline();navigate(location.hash.slice(1)||'overview',{scroll:false});
